-- SQL Technical Assessment Dataset
-- Tables: departments, staff
-- Compatible with PostgreSQL, MySQL, SQLite, and SQL Server

DROP TABLE IF EXISTS staff;
DROP TABLE IF EXISTS departments;

CREATE TABLE departments (
    department_id INT PRIMARY KEY,
    department_name VARCHAR(100) NOT NULL,
    location VARCHAR(100) NOT NULL,
    annual_budget DECIMAL(14, 2) NOT NULL
);

CREATE TABLE staff (
    staff_id INT PRIMARY KEY,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    gender VARCHAR(20) NOT NULL,
    is_transgender BOOLEAN NULL,
    department_id INT NULL,
    job_title VARCHAR(100) NOT NULL,
    salary DECIMAL(10, 2) NOT NULL,
    hire_date DATE NOT NULL,
    manager_id INT NULL,
    is_active BOOLEAN NOT NULL,
    CONSTRAINT fk_staff_department FOREIGN KEY (department_id) REFERENCES departments(department_id),
    CONSTRAINT fk_staff_manager FOREIGN KEY (manager_id) REFERENCES staff(staff_id)
);

